const x=$json.body ?? $json;
const lead={name:String(x.name||'').trim(),email:String(x.email||'').trim().toLowerCase(),company:String(x.company||'').trim(),size:Number(x.size||0),budget:Number(x.budget||0),urgency_days:Number(x.urgency_days||999),message:String(x.message||'').trim()};
const errs=[]; if(!lead.email.includes('@')) errs.push('invalid_email'); if(!lead.name) errs.push('missing_name');
let score=0; const reasons=[];
if(lead.email && !/(gmail|yahoo|hotmail|outlook)\./i.test(lead.email)){score+=10;reasons.push('business_email');}
if(lead.company){score+=10;reasons.push('company');}
if(lead.size>=2&&lead.size<=100){score+=15;reasons.push('target_size');}
if(lead.budget>=500){score+=20;reasons.push('budget');}
if(lead.urgency_days<=14){score+=15;reasons.push('urgent');}
if(/automat|api|crm|manual|repet|workflow|hubspot|sheet/i.test(lead.message)){score+=20;reasons.push('automation_pain');}
if(lead.message.length>=60){score+=10;reasons.push('detail');}
score=Math.min(100,score);
const route=score>=75?'HOT':score>=50?'WARM':'COLD';
return [{json:{...lead,valid:errs.length===0,errors:errs,score,reasons,route,processed_at:new Date().toISOString()}}];
